<?php $view->extend('layouts.admin');$view->section('content');?><div class="aho-admin-page"><div class="aho-admin-page__header"><div><h1>🎨 Builder Projeleri</h1><p>Site ve mobil builder projelerini yönetin.</p></div></div><form method="get" class="aho-card" style="display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin-bottom:18px"><div><label class="aho-form-label">Ara</label><input class="aho-form-input" name="q" value="<?=e($q??'')?>" placeholder="Proje, slug, müşteri"></div><div><label class="aho-form-label">Tür</label><select class="aho-form-input" name="kind"><option value="">Hepsi</option><option value="site" <?=($kind??'')==='site'?'selected':''?>>Site</option><option value="mobile" <?=($kind??'')==='mobile'?'selected':''?>>Mobile</option></select></div><button class="aho-btn aho-btn--primary">Filtrele</button></form><div class="aho-card" style="padding:0;overflow:auto"><table style="width:100%;border-collapse:collapse"><thead><tr><th style="padding:12px;text-align:left">Proje</th><th style="padding:12px">Müşteri</th><th style="padding:12px">Tür</th><th style="padding:12px">Sektör</th><th style="padding:12px">Durum</th><th style="padding:12px">Tarih</th></tr></thead><tbody><?php foreach($items as $p):?><tr style="border-top:1px solid var(--aho-color-border)"><td style="padding:12px"><strong><a href="/admin/<?=($p['kind']??'site')==='mobile'?'mobile-builder':'site-builder'?>/<?= (int)$p['id'] ?>"><?=e($p['name'])?></a></strong><br><small><?=e($p['slug'])?></small></td><td style="padding:12px"><?=e($p['email']??'-')?></td><td style="padding:12px"><?=($p['kind']??'site')==='mobile'?'Mobile':'Site'?></td><td style="padding:12px"><?=e($p['sector']??'-')?></td><td style="padding:12px"><?=e($p['status']??'draft')?></td><td style="padding:12px"><?=e($p['created_at']??'')?></td></tr><?php endforeach;?></tbody></table><?php if(!$items):?><div style="padding:40px;text-align:center">Henüz builder projesi yok.</div><?php endif;?></div></div><?php $view->endSection()